try{const focus='$service';const isAll=!focus||focus==='.+'||focus.indexOf('$')===0;
const series=data.series&&data.series[0];if(!series){return {data:[],layout:{annotations:[{text:'no data',showarrow:false,font:{color:'#888'}}],paper_bgcolor:'rgba(0,0,0,0)'}};}
const F=Object.fromEntries(series.fields.map(f=>[f.name,f.values||[]]));
const clients=F.client||[],servers=F.server||[],failed=F.failed||[],vals=F.Value||[],ct=F.connection_type||[],st=F.server_type||[],db=F.client_db_system||[];
// BFS reachable from focus
let reachable=null;
if(!isAll){const adj=new Map();for(let i=0;i<clients.length;i++){if(!adj.has(clients[i]))adj.set(clients[i],new Set());adj.get(clients[i]).add(servers[i]);}reachable=new Set([focus]);const q=[focus];while(q.length){const n=q.shift();for(const nx of (adj.get(n)||[])){if(!reachable.has(nx)){reachable.add(nx);q.push(nx);}}}}
const keep=i=>isAll||(reachable&&reachable.has(clients[i]));
// Determine kind per node
const kindOf={};for(let i=0;i<clients.length;i++){if(!keep(i))continue;kindOf['c::'+clients[i]]=kindOf['c::'+clients[i]]||'service';const isDb=(db[i]&&db[i].length>0)||['db','cache'].includes(st[i]);const isVn=ct[i]==='virtual_node';const k=isDb?'db':(isVn?'external':'service');const cur=kindOf['s::'+servers[i]];if(!cur||(cur==='service'&&k!=='service'))kindOf['s::'+servers[i]]=k;}
const namesSet=new Set();for(let i=0;i<clients.length;i++){if(!keep(i))continue;namesSet.add(clients[i]);namesSet.add(servers[i]);}
const names=[...namesSet];if(!names.length){return {data:[],layout:{annotations:[{text:'no flow reachable from '+focus,showarrow:false,font:{color:'#888'}}],paper_bgcolor:'rgba(0,0,0,0)'}};}
const idx=Object.fromEntries(names.map((n,i)=>[n,i]));
const svcPal=['#5794F2','#73BF69','#B877D9','#8AB8FF','#37872D','#1F60C4','#F2CC0C','#FF9830','#FA6400'];let svcI=0;
const nodeColor=names.map(n=>{const k=kindOf['s::'+n]||kindOf['c::'+n]||'service';if(k==='db')return '#FF780A';if(k==='external')return '#8E8E8E';return svcPal[(svcI++)%svcPal.length];});
const nodeLabel=names.map(n=>{const k=kindOf['s::'+n]||kindOf['c::'+n]||'service';return k==='db'?(n+' (db)'):(k==='external'?(n+' (ext)'):n);});
const src=[],tgt=[],v=[],lc=[],lab=[];
for(let i=0;i<clients.length;i++){if(!keep(i))continue;const c=clients[i],s=servers[i],f=String(failed[i])==='true',val=Number(vals[i])||0;src.push(idx[c]);tgt.push(idx[s]);v.push(val);lc.push(f?'rgba(224,47,68,0.55)':(kindOf['s::'+s]==='db'?'rgba(255,120,10,0.40)':'rgba(87,148,242,0.32)'));lab.push((f?'FAILED · ':'')+c+' → '+s+'  '+val.toFixed(3)+' rps');}
return {data:[{type:'sankey',orientation:'h',arrangement:'snap',valueformat:'.3f',valuesuffix:' rps',node:{label:nodeLabel,pad:18,thickness:22,line:{color:'rgba(0,0,0,0)',width:0},color:nodeColor},link:{source:src,target:tgt,value:v,color:lc,customdata:lab,hovertemplate:'%{customdata}<extra></extra>'}}],layout:{paper_bgcolor:'rgba(0,0,0,0)',plot_bgcolor:'rgba(0,0,0,0)',font:{color:'#d8d9da'},margin:{l:10,r:10,t:10,b:10}}};
}catch(e){return {data:[],layout:{annotations:[{text:'script error: '+e.message,showarrow:false,font:{color:'#e02f44'}}],paper_bgcolor:'rgba(0,0,0,0)'}};}

try{const focus='$service';const isAll=!focus||focus==='.+'||focus.indexOf('$')===0;
const series=data.series&&data.series[0];if(!series){return {data:[],layout:{annotations:[{text:'no data',showarrow:false,font:{color:'#888'}}],paper_bgcolor:'rgba(0,0,0,0)'}};}
const F=Object.fromEntries(series.fields.map(f=>[f.name,f.values||[]]));
const cs=F.client||[],ss=F.server||[],cops=F.client_operation_name||[],sops=F.server_operation_name||[],fl=F.failed||[],ct=F.connection_type||[],st=F.server_type||[],db=F.client_db_system||[],vs=F.Value||[];
if(!cs.length){return {data:[],layout:{annotations:[{text:'no rows',showarrow:false,font:{color:'#888'}}],paper_bgcolor:'rgba(0,0,0,0)'}};}
let reachable=null;if(!isAll){const adj=new Map();for(let i=0;i<cs.length;i++){if(!adj.has(cs[i]))adj.set(cs[i],new Set());adj.get(cs[i]).add(ss[i]);}reachable=new Set([focus]);const q=[focus];while(q.length){const n=q.shift();for(const nx of (adj.get(n)||[])){if(!reachable.has(nx)){reachable.add(nx);q.push(nx);}}}}
const rows=[];for(let i=0;i<cs.length;i++){if(!isAll&&!(reachable&&reachable.has(cs[i])))continue;const isDb=(db[i]&&db[i].length>0)||['db','cache'].includes(st[i]);const isVn=ct[i]==='virtual_node';rows.push({c:cs[i],s:ss[i],co:(cops[i]||'(unset)'),so:(sops[i]||'(unset)'),f:String(fl[i])==='true',v:Number(vs[i])||0,kindS:isDb?'db':(isVn?'external':'service')});}
if(!rows.length){return {data:[],layout:{annotations:[{text:'no flow reachable from '+focus,showarrow:false,font:{color:'#888'}}],paper_bgcolor:'rgba(0,0,0,0)'}};}
// Stage order: 0=client, 1=client_op, 2=server, 3=server_op
const stages=[new Map(),new Map(),new Map(),new Map()];
const keyOf=(s,r)=>s===0?'c::'+r.c:s===1?'co::'+r.c+'::'+r.co:s===2?'s::'+r.s:'so::'+r.s+'::'+r.so;
const labelAt=(s,r)=>[r.c,r.co,r.s,r.so][s];
for(const r of rows){for(let s=0;s<4;s++){const k=keyOf(s,r);if(!stages[s].has(k))stages[s].set(k,{label:labelAt(s,r),kind:s>=2?r.kindS:'service'});}}
const stageColor=['#5794F2','#B877D9','#73BF69','#FF9830'];
let labels=[],colors=[],idx={},i=0;
for(let s=0;s<4;s++){for(const [k,n] of stages[s]){idx[k]=i++;let lbl=n.label;let col=stageColor[s];if(n.kind==='db'){col='#FF780A';lbl=n.label+' (db)';}else if(n.kind==='external'){col='#8E8E8E';lbl=n.label+' (ext)';}labels.push(lbl);colors.push(col);}}
const src=[],tgt=[],val=[],lc=[],cd=[];
const addLink=(a,b,r)=>{src.push(idx[a]);tgt.push(idx[b]);val.push(r.v);lc.push(r.f?'rgba(224,47,68,0.55)':(r.kindS==='db'?'rgba(255,120,10,0.35)':'rgba(140,160,200,0.28)'));cd.push((r.f?'FAILED · ':'')+r.c+'.'+r.co+' → '+r.s+'.'+r.so+'  '+r.v.toFixed(3)+' rps');};
for(const r of rows){addLink(keyOf(0,r),keyOf(1,r),r);addLink(keyOf(1,r),keyOf(2,r),r);addLink(keyOf(2,r),keyOf(3,r),r);}
return {data:[{type:'sankey',orientation:'h',arrangement:'snap',valueformat:'.3f',valuesuffix:' rps',node:{label:labels,pad:14,thickness:16,color:colors,line:{width:0}},link:{source:src,target:tgt,value:val,color:lc,customdata:cd,hovertemplate:'%{customdata}<extra></extra>'}}],layout:{paper_bgcolor:'rgba(0,0,0,0)',plot_bgcolor:'rgba(0,0,0,0)',font:{color:'#d8d9da'},margin:{l:10,r:10,t:10,b:10}}};
}catch(e){return {data:[],layout:{annotations:[{text:'script error: '+e.message,showarrow:false,font:{color:'#e02f44'}}],paper_bgcolor:'rgba(0,0,0,0)'}};}

try{const focus='$service';const isAll=!focus||focus==='.+'||focus.indexOf('$')===0;
const a=data.series&&data.series[0],b=data.series&&data.series[1];if(!a){return {data:[]};}
const FA=Object.fromEntries(a.fields.map(f=>[f.name,f.values||[]]));
const FB=b?Object.fromEntries(b.fields.map(f=>[f.name,f.values||[]])):{};
const clients=FA.client||[],servers=FA.server||[],vals=FA.Value||[];
let reachable=null;if(!isAll){const adj=new Map();for(let i=0;i<clients.length;i++){if(!adj.has(clients[i]))adj.set(clients[i],new Set());adj.get(clients[i]).add(servers[i]);}reachable=new Set([focus]);const q=[focus];while(q.length){const n=q.shift();for(const nx of (adj.get(n)||[])){if(!reachable.has(nx)){reachable.add(nx);q.push(nx);}}}}
const keep=i=>isAll||(reachable&&reachable.has(clients[i]));
const rowSet=new Set(),colSet=new Set();
for(let i=0;i<clients.length;i++){if(keep(i)){rowSet.add(clients[i]);colSet.add(servers[i]);}}
const rows=[...rowSet].sort();const cols=[...colSet].sort();
if(!rows.length){return {data:[],layout:{annotations:[{text:'no flow reachable from '+focus,showarrow:false,font:{color:'#888'}}],paper_bgcolor:'rgba(0,0,0,0)'}};}
const rIdx=Object.fromEntries(rows.map((n,i)=>[n,i]));
const cIdx=Object.fromEntries(cols.map((n,i)=>[n,i]));
const Z=rows.map(()=>cols.map(()=>null));
for(let i=0;i<clients.length;i++){if(!keep(i))continue;const r=rIdx[clients[i]],c=cIdx[servers[i]];if(r!=null&&c!=null)Z[r][c]=Number(vals[i])||0;}
const FK={};if(b){const c2=FB.client||[],s2=FB.server||[],v2=FB.Value||[];for(let i=0;i<c2.length;i++)FK[c2[i]+'>>'+s2[i]]=Number(v2[i])||0;}
const hover=rows.map(r=>cols.map(c=>{const v=Z[rows.indexOf(r)][cols.indexOf(c)];if(v==null)return r+' → '+c+'<br>(no traffic)';const fr=FK[r+'>>'+c]||0;return r+' → '+c+'<br>'+v.toFixed(3)+' rps<br>failed: '+(fr*100).toFixed(2)+'%';}));
return {data:[{type:'heatmap',z:Z,x:cols,y:rows,colorscale:[[0,'#1f2026'],[0.0001,'#0d1b3a'],[0.2,'#1f60c4'],[0.5,'#73bf69'],[0.8,'#ff9830'],[1,'#e02f44']],showscale:true,colorbar:{title:'rps',thickness:10,tickfont:{color:'#d8d9da'},titlefont:{color:'#d8d9da'}},hoverinfo:'text',text:hover,xgap:2,ygap:2}],layout:{paper_bgcolor:'rgba(0,0,0,0)',plot_bgcolor:'rgba(0,0,0,0)',font:{color:'#d8d9da'},margin:{l:140,r:10,t:30,b:120},xaxis:{title:'server',side:'top',tickangle:-40,tickfont:{size:11}},yaxis:{title:'client',autorange:'reversed',tickfont:{size:11}}}};
}catch(e){return {data:[],layout:{annotations:[{text:'script error: '+e.message,showarrow:false,font:{color:'#e02f44'}}]}};}

try{const focus='$service';const isAll=!focus||focus==='.+'||focus.indexOf('$')===0;
const s=data.series&&data.series[0];if(!s){return {data:[]};}
const F=Object.fromEntries(s.fields.map(f=>[f.name,f.values||[]]));
const cts=F.client_type||[],cs=F.client||[],ss=F.server||[],sos=F.server_operation_name||[],vs=F.Value||[];
let reachable=null;if(!isAll){const adj=new Map();for(let i=0;i<cs.length;i++){if(!adj.has(cs[i]))adj.set(cs[i],new Set());adj.get(cs[i]).add(ss[i]);}reachable=new Set([focus]);const q=[focus];while(q.length){const n=q.shift();for(const nx of (adj.get(n)||[])){if(!reachable.has(nx)){reachable.add(nx);q.push(nx);}}}}
const nodes=new Map();
const push=(id,parent,label,val)=>{const n=nodes.get(id)||{id,parent,label,val:0};n.val+=val;nodes.set(id,n);};
push('root','','traffic',0);
let added=0;
for(let i=0;i<cs.length;i++){if(!isAll&&!(reachable&&reachable.has(cs[i])))continue;const ct=cts[i]||'(unknown)',c=cs[i]||'(unknown)',sv=ss[i]||'(unknown)',so=sos[i]||'(unset)',v=Number(vs[i])||0;const k1='ct::'+ct,k2=k1+'|c::'+c,k3=k2+'|s::'+sv,k4=k3+'|so::'+so;push(k1,'root',ct,v);push(k2,k1,c,v);push(k3,k2,sv,v);push(k4,k3,so,v);push('root','','traffic',v);added++;}
if(!added){return {data:[],layout:{annotations:[{text:'no flow reachable from '+focus,showarrow:false,font:{color:'#888'}}],paper_bgcolor:'rgba(0,0,0,0)'}};}
const ids=[],parents=[],labels=[],values=[];
for(const [k,n] of nodes){ids.push(k);parents.push(n.parent);labels.push(n.label);values.push(n.val);}
return {data:[{type:'sunburst',ids,parents,labels,values,branchvalues:'total',hovertemplate:'%{label}<br>%{value:.3f} rps<extra></extra>',insidetextorientation:'radial',marker:{colors:values,colorscale:'Viridis',showscale:false,line:{color:'#1f2026',width:1}}}],layout:{paper_bgcolor:'rgba(0,0,0,0)',plot_bgcolor:'rgba(0,0,0,0)',font:{color:'#d8d9da',size:11},margin:{l:5,r:5,t:5,b:5}}};
}catch(e){return {data:[],layout:{annotations:[{text:'script error: '+e.message,showarrow:false,font:{color:'#e02f44'}}]}};}

try{const focus='$service';const isAll=!focus||focus==='.+'||focus.indexOf('$')===0;
const s=data.series&&data.series[0];if(!s){return {data:[]};}
const F=Object.fromEntries(s.fields.map(f=>[f.name,f.values||[]]));
const cts=F.client_type||[],cs=F.client||[],ss=F.server||[],fl=F.failed||[],vs=F.Value||[];
let reachable=null;if(!isAll){const adj=new Map();for(let i=0;i<cs.length;i++){if(!adj.has(cs[i]))adj.set(cs[i],new Set());adj.get(cs[i]).add(ss[i]);}reachable=new Set([focus]);const q=[focus];while(q.length){const n=q.shift();for(const nx of (adj.get(n)||[])){if(!reachable.has(nx)){reachable.add(nx);q.push(nx);}}}}
const dimC=[],dimCT=[],dimS=[],counts=[],colors=[];
for(let i=0;i<cs.length;i++){if(!isAll&&!(reachable&&reachable.has(cs[i])))continue;dimC.push(cs[i]||'(unknown)');dimCT.push(cts[i]||'(unknown)');dimS.push(ss[i]||'(unknown)');counts.push(Number(vs[i])||0);colors.push(String(fl[i])==='true'?1:0);}
if(!counts.length){return {data:[],layout:{annotations:[{text:'no flow reachable from '+focus,showarrow:false,font:{color:'#888'}}],paper_bgcolor:'rgba(0,0,0,0)'}};}
return {data:[{type:'parcats',dimensions:[{label:'client',values:dimC},{label:'client_type',values:dimCT},{label:'server',values:dimS}],counts:counts,line:{color:colors,colorscale:[[0,'#5794F2'],[1,'#E02F44']],shape:'hspline'},hoveron:'color',hoverinfo:'count+probability',arrangement:'freeform',labelfont:{size:13,color:'#d8d9da'},tickfont:{size:11,color:'#d8d9da'}}],layout:{paper_bgcolor:'rgba(0,0,0,0)',plot_bgcolor:'rgba(0,0,0,0)',font:{color:'#d8d9da'},margin:{l:80,r:80,t:30,b:30}}};
}catch(e){return {data:[],layout:{annotations:[{text:'script error: '+e.message,showarrow:false,font:{color:'#e02f44'}}],paper_bgcolor:'rgba(0,0,0,0)'}};}
